/* ------------------------------------------------------------------ */
/* Taish Gaming — Canonical Verified Database                          */
/* Strict adherence to information confidence levels:                */
/* OFFICIAL | CONFIRMED | REPORTED | RUMORED | SPECULATION            */
/* ------------------------------------------------------------------ */

export type ConfidenceLevel = "OFFICIAL" | "CONFIRMED" | "REPORTED" | "RUMORED" | "SPECULATION";

export interface CanonicalVehicle {
  id: string;
  slug: string;
  name: string;
  manufacturer: string;
  klass: "Super Car" | "Sports Car" | "Muscle Car" | "Classic sedan" | "Off-Road" | "Motorcycle" | "Dirt Bike" | "Boat" | "Helicopter" | "Plane" | "Van" | "Commercial";
  img: string;
  filter?: string;
  topSpeed: number | null; // mph, null = unconfirmed
  acceleration: number | null; // 0-60 in seconds, null = unconfirmed
  braking: number | null; // score 0-100, null = unconfirmed
  handling: number | null; // score 0-100, null = unconfirmed
  power: number | null; // hp, null = unconfirmed
  weight: string;
  seating: number | null;
  drivetrain: "RWD" | "AWD" | "FWD" | "Unknown";
  price: number | null; // null if unconfirmed
  priceDisplay: string;
  purchaseLocation: string;
  spawnLocations: string[];
  customizationOptions: string[];
  confidence: ConfidenceLevel;
  source: string;
  description: string;
  /* Honest spotting notes shown on the detail page (analyst identification,
     labelled as such — never a stat, price or spawn claim). */
  notes?: string;
  featured?: boolean;

  /* ---- Deep-dive optional fields (CMS-managed, added Oct 2026) ---- */
  // Performance ratings 0-100
  traction?: number;
  cornering?: number;
  launch?: number;
  reverseSpeed?: number;
  torque?: number;
  // Economy
  resalePrice?: number | null;
  insuranceCost?: number | null;
  upgradeCost?: number | null;
  repairCost?: number | null;
  storageCost?: number | null;
  // Engine / mechanical
  engineType?: string;
  engineSize?: string;
  transmission?: string;
  gears?: number;
  fuelType?: string;
  turbo?: boolean;
  electric?: boolean;
  // Characteristics
  doors?: number;
  convertible?: boolean;
  roofType?: string;
  trunkCapacity?: string;
  offroadRating?: number;
  waterRating?: number;
  amphibious?: boolean;
  bulletResistance?: number;
  explosionResistance?: number;
  // Special features & ratings
  armorRating?: number;
  weaponized?: boolean;
  driftRating?: number;
  specialAbility?: string;
  features?: string[];
  // Customization, audio, meta
  customization?: string[];
  soundRating?: number;
  engineSound?: string;
  exhaustSound?: string;
  horn?: string;
  turboSound?: string;
  gearShiftSound?: string;
  availability?: string;
  gallery?: string[];
  tags?: string[];
}

export interface CanonicalWeapon {
  id: string;
  slug: string;
  name: string;
  klass: "Pistol" | "Revolver" | "SMG" | "Assault Rifle" | "Shotgun" | "Sniper Rifle" | "Heavy" | "Melee" | "Throwable";
  damage: number | null; // score 0-100, null = unconfirmed
  fireRate: number | null; // score 0-100, null = unconfirmed
  accuracy: number | null; // score 0-100, null = unconfirmed
  range: number | null; // score 0-100, null = unconfirmed
  handling: number | null; // score 0-100, null = unconfirmed
  reloadTime: string;
  magazineSize: number | null;
  ammoType: string;
  price: number | null;
  priceDisplay: string;
  rarity: "Common" | "Rare" | "Epic" | "Legendary" | "Featured";
  locations: string[];
  attachments: string[];
  confidence: ConfidenceLevel;
  source: string;
  description: string;
  img: string;
  /* Honest spotting notes shown on the detail page (analyst identification,
     labelled as such — never a stat, price or spawn claim). */
  notes?: string;

  /* ---- Deep-dive optional fields (CMS-managed, added Oct 2026) ---- */
  // Stats 0-100 (unless noted)
  reload?: number; // reload speed rating (higher = faster)
  ammoCapacity?: number; // reserve rounds
  recoil?: number; // recoil rating (higher = more controllable)
  mobility?: number;
  projectileSpeed?: number;
  headshotMultiplier?: number;
  damageFalloff?: number; // 0-100 (higher = less falloff)
  fireMode?: string; // Single / Burst / Automatic
  features?: string[]; // Suppressor, Scope, Armor Penetration, ...
  // Economy
  ammoCost?: number | null;
  upgradeCost?: number | null;
  // Meta
  manufacturer?: string;
  availability?: string;
  featured?: boolean;
  gallery?: string[];
  tags?: string[];
  customization?: string[];
}

export interface CanonicalMission {
  id: string;
  slug: string;
  title: string;
  type: "Main Story" | "Side Contract" | "Heist" | "Random Encounter" | "Strangers & Freaks";
  character: "Lucia" | "Jason" | "Both" | "Any";
  difficulty: "Easy" | "Medium" | "Hard" | "Extreme";
  duration: string; // e.g. "15-20 min"
  district: string;
  cashReward: number | null;
  cashRewardDisplay: string;
  otherRewards: string[];
  requirements: string[];
  objectives: string[];
  choices: string[];
  outcomes: string[];
  unlocks: string[];
  relatedMissions: string[];
  confidence: ConfidenceLevel;
  source: string;
  description: string;
  guideTips: string[];
  img: string;
}

export interface CanonicalLocation {
  id: string;
  slug: string;
  name: string;
  district: string;
  category: "Mission" | "Vehicle Spawn" | "Weapon Cache" | "Property" | "Business" | "Shop" | "Restaurant / Bar" | "Garage" | "Safehouse" | "Airport / Helipad" | "Collectible" | "Easter Egg" | "Random Event" | "Point of Interest";
  desc: string;
  top: string; // percentage on map
  left: string; // percentage on map
  hours?: string;
  threatLevel?: "Low" | "Medium" | "High" | "Restricted Area" | "Unknown";
  relatedVehicles?: string[];
  relatedWeapons?: string[];
  relatedMissions?: string[];
  confidence: ConfidenceLevel;
  source: string;
  img: string;
  verified: boolean;
}

export interface CanonicalProperty {
  id: string;
  slug: string;
  name: string;
  district: string;
  type: "Safehouse" | "Luxury Penthouse" | "Nightclub" | "Chop Shop Garage" | "Commercial Warehouse" | "Marina Dock" | "Aviation Hangar";
  price: number | null;
  priceDisplay: string;
  garageCapacity: number;
  passiveIncomePerHour: number | null;
  passiveIncomeDisplay: string;
  features: string[];
  upgrades: string[];
  requirements: string[];
  confidence: ConfidenceLevel;
  source: string;
  desc: string;
  img: string;
  mapCoords: { top: string; left: string };
}

export interface CanonicalCollectible {
  id: string;
  slug: string;
  title: string;
  category: "Hidden Packages" | "Stunt Jumps" | "Rebel Radio" | "Wildlife Photos" | "Weapon Parts" | "Easter Eggs";
  district: string;
  reward: string;
  requirements: string;
  description: string;
  guideTip: string;
  coordinates: { top: string; left: string };
  confidence: ConfidenceLevel;
  source: string;
  img: string;
}

export interface CanonicalMoneyMethod {
  id: string;
  title: string;
  category: "Heist" | "Passive Business" | "High-Stakes Contract" | "Street Smuggling" | "Asset Speculation";
  moneyPerHour: number;
  moneyPerHourDisplay: string;
  difficulty: "Easy" | "Medium" | "Hard" | "Extreme";
  minInvestment: number;
  minInvestmentDisplay: string;
  timeToPayout: string;
  soloFriendly: boolean;
  coopRecommended: boolean;
  riskTolerance: "Low" | "Medium" | "High";
  requiredLevel: "Beginner" | "Intermediate" | "Veteran";
  requirements: string[];
  strategySteps: string[];
  whyRecommended: string;
  confidence: ConfidenceLevel;
  source: string;
}

