    confidence: "REPORTED",
    source: "KeenGamer 'GTA 6: Watson Bay Safehouse Walkthrough' (25 Nov 2026) — Black Moth Kamacho in the downstairs garage of the Watson Bay Safehouse, Watson Bay; corroborated by ShowGamer, Dexerto, Game8, GTA6Info and GameRant (23 Nov 2026)",
    description: "Standout Canis Kamacho customized by La Polilla Negra, with a black-and-white camouflage finish. Found in the garage of the Watson Bay Safehouse, one of the safehouse's four Key Valuables.",
    notes: "KeenGamer (25 Nov 2026): the Black Moth Kamacho is parked inside the downstairs garage of the Watson Bay Safehouse, on the side of the house facing the main gate — a Standout version of the Canis Kamacho with 6 seats, 6 trunk slots and no tracker. It is one of the safehouse's four Key Valuables, alongside the La Polilla Negra VF-G1 assault rifle, the B&G Ark Royal Quantum watch and the locked safe (code 1819). ShowGamer, GTA6Info, Dexerto and Game8 agree on the garage, the safe code and the four valuables; GameRant ('How to get La Polilla Negra VF-G1 and Canis Black Moth Kamacho', 23 Nov) agrees too. KeenGamer lists a $16,315 sell value at Moses and a $6,700 registration fee — a single-outlet figure, so the price stays TBA. Dexerto lists in-game menu ratings (Speed 5.4, Acceleration 6.9, Asphalt Handling 3, Off-Road Handling 8.3, Strength 3.7) — reported, not verified from a menu screenshot, so all stats stay null. Game8: enter by climbing the blue-tarp fence at the back; the property is guarded by La Polilla Negra mercenaries. One outlet (gamer.org) spells it 'Camacho' — a typo; Kamacho per Dexerto, KeenGamer, Game8 and ShowGamer. The base Canis Kamacho is a returning GTA Online off-road vehicle; this Black Moth variant is the distinct in-game named standout. Register it at Moses once his garage opens in Chapter 2, or sell it there.",
