    confidence: "REPORTED",
    source: "KeenGamer 'GTA 6: How to Get a Tank – Secret Bunker Quest' — Hauners Ridgway in the IAA Black Site hangar near Big Pine; corroborated by RetroBroker, LeonidaHub and GamesFuze",
    description: "1940s vintage military mini-tank hidden in the IAA Black Site hangar near Big Pine — the reward at the end of the President Russo bunker investigation. Fitted with a rotating turret that fires explosive shells; it respawns in its hangar if lost.",
    notes: "KeenGamer: the Hauners Ridgway is an older military tank hidden inside an IAA underground facility near Big Pine, unlocked by following the secret President Russo bunker investigation — a second tank beside the Hauners Rhino, and unlike the Rhino it can be accessed again after unlocking its secret storage facility. The chain: veteran Jose Bermudez by the Friends of Freedom monument on Catalan Blvd, Downtown Vice City, sends the player to his apartment on NW 4th Avenue, Little Cuba; the Sharktooth Island bunker north of Waning Sands opens with code 010317; the safe inside opens with 2975 (radio numbers 5297 reshuffled by Protocol #2, 2341) and holds Russo's 1922 Pistol plus a photo marked OBSESS; the photo's code 085355 opens the tree keypad hatch of the second bunker, where restoring power and pressing the control-room button opens the hangar holding the tank and the Cold War 556. RetroBroker, LeonidaHub and GamesFuze agree on all three codes and the Big Pine hangar. Caveats: guides disagree on the exact hatch spot — LeonidaHub documents west of Big Pine (Guided), north-west of Grassrivers near Big Pine (KeenGamer, Khel Now, TechWiser, Beebom) and south of the Ammu-Nation by the highway (GameRant, GamingAlly, GTAScoop) — so the entry names the facility, not a pin. A LordKebun reel's 08535 is a five-digit typo against 085355. LeonidaHub: the tank cannot be registered as a personal vehicle, but it respawns in its hangar. Spelling settled to Ridgway (KeenGamer, RetroBroker, LeonidaHub); earlier 'Ridgeway' spellings are now superseded. In-game class is Military; the site's vehicle classes have no Military value, so this entry is filed under Off-Road, as with the Rhino. Not for sale — world find only.",
